1	/**
2	 * Differential harness: runs the reference executable and the Node port with
3	 * byte-identical argv, and compares stdout / stderr / exit code exactly.
4	 *
5	 * argv bytes are delivered through bash $'...' quoting so that arbitrary
6	 * (including invalid-UTF-8) bytes reach execve untouched. NUL is not
7	 * representable in argv at all, so it is rejected up front.
8	 */
9	import { spawnSync } from 'node:child_process';
10	
11	const PY = '/workspace/dataset/test7_executable';
12	const JS = '/output/test7.mjs';
13	
14	/** Quote a Buffer as a bash $'...' literal, escaping every byte explicitly. */
15	function bashQuote(buf) {
16	  let out = "$'";
17	  for (const b of buf) {
18	    if (b === 0) throw new Error('NUL cannot appear in argv');
19	    out += '\\x' + b.toString(16).padStart(2, '0');
20	  }
21	  return out + "'";
22	}
23	
24	export function toBuf(v) {
25	  return Buffer.isBuffer(v) ? v : Buffer.from(String(v), 'utf8');
26	}
27	
28	/** Run one argv vector (array of strings/Buffers) against both programs. */
29	export function runCase(argv, env = {}) {
30	  const quoted = argv.map((a) => bashQuote(toBuf(a))).join(' ');
31	  const envPrefix = Object.entries(env)
32	    .map(([k, v]) => `${k}=${bashQuote(toBuf(v))}`)
33	    .join(' ');
34	  const prefix = envPrefix ? envPrefix + ' ' : '';
35	
36	  const run = (cmd) =>
37	    spawnSync('/bin/bash', ['-c', `${prefix}${cmd} ${quoted}`], { maxBuffer: 1 << 26 });
38	
39	  const py = run(PY);
40	  const js = run(`node ${JS}`);
41	  return {
42	    py: { out: py.stdout, err: py.stderr, code: py.status },
43	    js: { out: js.stdout, err: js.stderr, code: js.status },
44	  };
45	}
46	
47	/**
48	 * Compare one case. stdout and exit code must match byte for byte. stderr is
49	 * compared after masking PyInstaller's `[PYI-<pid>:ERROR]` line, whose pid can
50	 * never match across two different processes.
51	 */
52	export function checkCase(argv, env = {}) {
53	  const { py, js } = runCase(argv, env);
54	  const problems = [];
55	  if (!py.out.equals(js.out)) {
56	    problems.push(`stdout differs\n  py: ${py.out.toString('latin1')}\n  js: ${js.out.toString('latin1')}`);
57	  }
58	  if (py.code !== js.code) problems.push(`exit code differs: py=${py.code} js=${js.code}`);
59	
60	  const mask = (b) => b.toString('utf8').replace(/\[PYI-\d+:ERROR\]/g, '[PYI:ERROR]');
61	  if (mask(py.err) !== mask(js.err)) {
62	    problems.push(`stderr differs\n  py: ${mask(py.err)}\n  js: ${mask(js.err)}`);
63	  }
64	  return problems;
65	}
66	
67	/** Run a list of cases, print failures, return the failure count. */
68	export function runSuite(name, cases) {
69	  let failed = 0;
70	  for (const entry of cases) {
71	    const argv = Array.isArray(entry) ? entry : entry.argv;
72	    const env = Array.isArray(entry) ? {} : entry.env || {};
73	    const label = Array.isArray(entry)
74	      ? argv.map((a) => toBuf(a).toString('latin1')).join(' | ')
75	      : entry.label || '';
76	    const problems = checkCase(argv, env);
77	    if (problems.length > 0) {
78	      failed += 1;
79	      process.stdout.write(`FAIL [${name}] ${label}\n`);
80	      for (const p of problems) process.stdout.write('  ' + p.replace(/\n/g, '\n  ') + '\n');
81	    }
82	  }
83	  process.stdout.write(`[${name}] ${cases.length - failed}/${cases.length} passed\n`);
84	  return failed;
85	}
