1	/**
2	 * textwrap.mjs — the slice of `textwrap.wrap` that argparse's HelpFormatter
3	 * needs: collapse whitespace, then greedily fill lines, breaking a word only
4	 * when it cannot fit on a line by itself.
5	 */
6	
7	/** `argparse.HelpFormatter._whitespace_matcher.sub(' ', text).strip()` */
8	export function collapseWhitespace(text) {
9	  return text.replace(/[\t\n\x0b\f\r ]+/g, ' ').replace(/^ +| +$/g, '');
10	}
11	
12	/**
13	 * `textwrap.wrap(text, width)` with argparse's defaults. Returns a list of
14	 * lines; an all-whitespace input yields an empty list, as in Python.
15	 */
16	export function wrapText(text, width) {
17	  const normalized = collapseWhitespace(text);
18	  if (normalized === '') return [];
19	  const limit = Math.max(1, width);
20	
21	  const lines = [];
22	  let current = '';
23	
24	  for (let word of normalized.split(' ')) {
25	    if (word === '') continue;
26	
27	    if (current === '') {
28	      // A word longer than the whole line gets chopped (break_long_words=True).
29	      while (word.length > limit) {
30	        lines.push(word.slice(0, limit));
31	        word = word.slice(limit);
32	      }
33	      current = word;
34	      continue;
35	    }
36	
37	    if (current.length + 1 + word.length <= limit) {
38	      current += ' ' + word;
39	      continue;
40	    }
41	
42	    lines.push(current);
43	    current = '';
44	    while (word.length > limit) {
45	      lines.push(word.slice(0, limit));
46	      word = word.slice(limit);
47	    }
48	    current = word;
49	  }
50	
51	  if (current !== '') lines.push(current);
52	  return lines;
53	}
54	
55	/** `textwrap.fill(text, width)` */
56	export function fillText(text, width, indent = '') {
57	  return wrapText(text, width - indent.length)
58	    .map((line) => indent + line)
59	    .join('\n');
60	}
