/**
 * Campaign: help-formatting
 *
 * Byte-compares --help output and the usage line printed on every error path,
 * across a dense sweep of COLUMNS values (valid, invalid, absent, exotic).
 */
import { runSuite } from '/tmp/dh/harness.mjs';

const phase = process.argv[2] || 'all';
let total = 0;
let failed = 0;
const run = (name, cases) => {
  total += cases.length;
  failed += runSuite(name, cases);
};

// ---------------------------------------------------------------- width lists

// The widths named by the campaign.
const NAMED = ['10','11','12','15','18','20','24','25','30','40','50','60','70','79','80','81','100','200','1000'];

// Dense sweep: every width 1..140, plus assorted larger ones.
const DENSE = [];
for (let i = 1; i <= 140; i += 1) DENSE.push(String(i));
const BIG = ['141','200','255','256','300','500','999','1000','1001','2000','4096','65535','65536','100000','2147483647','2147483648','4294967296','9007199254740991','9007199254740993','99999999999999999999'];

// Invalid / exotic COLUMNS values. Python does int(os.environ['COLUMNS']) and
// treats ValueError *and* any value <= 0 as "ask the terminal", which under a
// pipe falls back to 80.
const INVALID = [
  '0','-0','-1','-5','-80','-2147483648',
  'abc','','   ','+','-','--','1-','1+',
  '12abc','abc12','12 34','12,34','12.0','12.5','0.5','.5','1e3','1E3','0x10','0X10','0b1010','0o17','1j',
  '1_0','1_000','10_','_10','１２','٣٠','۴۰','½','Ⅷ',
  ' 12','12 ','\t12\t','\n12\n','\r12\r','\x0b12\x0c',' +12 ',' -12 ',
  '007','0000000080','+80','+ 80','8 0',
  'inf','nan','Infinity','None','True','false','null','80.','80;','80\x00'.replace('\x00',''),
  ' 12 ','​12','12​',
];

// ---------------------------------------------------------------- argv vectors

const HELP_ARGVS = [
  { key: 'help-long', argv: ['--help'] },
  { key: 'help-short', argv: ['-h'] },
  { key: 'help-abbrev', argv: ['--h'] },
  { key: 'help-abbrev2', argv: ['--he'] },
  { key: 'help-after-args', argv: ['--a', '1', '--b', '2', '-h'] },
  { key: 'help-before-args', argv: ['-h', '--a', '1'] },
];

const ERROR_ARGVS = [
  { key: 'err-none', argv: [] },
  { key: 'err-missing-b', argv: ['--a', '1'] },
  { key: 'err-missing-a', argv: ['--b', '1'] },
  { key: 'err-missing-both-extra', argv: ['zz'] },
  { key: 'err-unrec-dashdash', argv: ['--a', '1', '--b', '2', '--'] },
  { key: 'err-unrec-plain', argv: ['--a', '1', '--b', '2', 'extra'] },
  { key: 'err-unrec-opt', argv: ['--a', '1', '--b', '2', '--zzz'] },
  { key: 'err-expected-one', argv: ['--a'] },
  { key: 'err-expected-one2', argv: ['--a', '--b', '2'] },
  { key: 'err-ignored-explicit', argv: ['--help=x'] },
  { key: 'err-ignored-explicit-short', argv: ['-hx'] },
  { key: 'err-unrec-long', argv: ['--a', '1', '--b', '2', 'x'.repeat(200)] },
  {
    key: 'err-unrec-many',
    argv: ['--a', '1', '--b', '2', ...Array.from({ length: 25 }, (_, i) => `tok${i}`)],
  },
  { key: 'err-unrec-unicode', argv: ['--a', '1', '--b', '2', 'é中文😀'.repeat(20)] },
  { key: 'err-ambiguous-ish', argv: ['--', '--a', '1', '--b', '2'] },
];

const OK_ARGVS = [{ key: 'ok', argv: ['--a', '1', '--b', '2'] }];

// ---------------------------------------------------------------- case builder

function build(widths, argvs, tag, extraEnv = {}) {
  const cases = [];
  for (const w of widths) {
    for (const a of argvs) {
      cases.push({
        argv: a.argv,
        env: { COLUMNS: w, ...extraEnv },
        label: `${tag} COLUMNS=${JSON.stringify(w)} ${a.key}`,
      });
    }
  }
  return cases;
}

function buildUnset(argvs, tag, extraEnv = {}) {
  return argvs.map((a) => ({
    argv: a.argv,
    env: { ...extraEnv },
    label: `${tag} COLUMNS-unset ${a.key}`,
  }));
}

// ---------------------------------------------------------------- phases

if (phase === 'named' || phase === 'all') {
  run('named-widths-help', build(NAMED, HELP_ARGVS, 'named'));
  run('named-widths-err', build(NAMED, ERROR_ARGVS, 'named'));
  run('named-widths-ok', build(NAMED, OK_ARGVS, 'named'));
  run('unset-columns', buildUnset([...HELP_ARGVS, ...ERROR_ARGVS, ...OK_ARGVS], 'unset'));
}

if (phase === 'dense' || phase === 'all') {
  run('dense-help', build(DENSE, [HELP_ARGVS[0]], 'dense'));
  run('dense-usage-err', build(DENSE, [ERROR_ARGVS[0]], 'dense'));
  run('dense-usage-unrec', build(DENSE, [ERROR_ARGVS[4]], 'dense'));
}

if (phase === 'big' || phase === 'all') {
  run('big-help', build(BIG, [HELP_ARGVS[0], ERROR_ARGVS[0]], 'big'));
}

if (phase === 'invalid' || phase === 'all') {
  run('invalid-help', build(INVALID, [HELP_ARGVS[0]], 'invalid'));
  run('invalid-err', build(INVALID, [ERROR_ARGVS[0]], 'invalid'));
}

if (phase === 'misc' || phase === 'all') {
  // LINES must not influence anything; COLUMNS still wins.
  run(
    'lines-noise',
    build(['10', '40', '80'], [HELP_ARGVS[0], ERROR_ARGVS[0]], 'lines', { LINES: '5' }),
  );
  run('lines-only', buildUnset([HELP_ARGVS[0], ERROR_ARGVS[0]], 'lines-only', { LINES: '5' }));
  // TERM / locale should not matter either.
  run(
    'env-noise',
    build(['13', '37'], [HELP_ARGVS[0], ERROR_ARGVS[0]], 'envnoise', {
      TERM: 'dumb',
      LC_ALL: 'C',
      LANG: 'C',
    }),
  );
}

process.stdout.write(`\nTOTAL ${total - failed}/${total} passed (${failed} failures)\n`);

