345	  /** `parse_args` */
346	  parseArgs(args) {
347	    const [namespace, extras] = this.parseKnownArgs(args);
348	    if (extras.length > 0) {
349	      this.error(`unrecognized arguments: ${extras.join(' ')}`);
350	    }
351	    return namespace;
352	  }
