354	  /** `parse_known_args` / `_parse_known_args` */
355	  parseKnownArgs(argStrings) {
356	    const args = Array.from(argStrings);
357	    const namespace = new Namespace();
358	    for (const action of this.actions) {
359	      if (action.action === 'store') namespace[action.dest] = action.defaultValue;
360	    }
361	
362	    // Classify each argument: 'O' option, 'A' value, '-' the "--" separator.
363	    const pattern = [];
364	    const optionIndices = new Map();
365	    let sawSeparator = false;
366	    for (let i = 0; i < args.length; i += 1) {
367	      if (sawSeparator) {
368	        pattern.push('A');
369	        continue;
370	      }
371	      if (args[i] === '--') {
372	        pattern.push('-');
373	        sawSeparator = true;
374	        continue;
375	      }
376	      const optionTuple = this.parseOptional(args[i]);
377	      if (optionTuple === null) {
378	        pattern.push('A');
379	      } else {
380	        optionIndices.set(i, optionTuple);
381	        pattern.push('O');
382	      }
383	    }
384	
385	    const seenActions = new Set();
386	    const extras = [];
387	
388	    const takeAction = (action, values) => {
389	      seenActions.add(action);
390	      if (action.action === 'help') {
391	        this.printHelp();
392	        throw new SystemExit(0);
393	      }
394	      // type=str is the identity conversion.
395	      namespace[action.dest] = action.nargs === 0 ? true : values[0];
396	    };
397	
398	    /**
399	     * `consume_optional`. Actions are collected into `actionTuples` and only
400	     * applied once the loop settles, so an error raised part-way through a
401	     * concatenated short-option chain applies nothing at all.
402	     */
403	    const consumeOptional = (startIndex) => {
404	      let [action, optionString, sep, explicitArg] = optionIndices.get(startIndex);
405	      const actionTuples = [];
406	      let stop;
407	
408	      for (;;) {
409	        if (action === null) {
410	          extras.push(args[startIndex]);
411	          return startIndex + 1;
412	        }
413	
414	        if (explicitArg !== null) {
415	          const argCount = this.matchArgument(action, ['A']);
416	          const chars = this.prefixChars;
417	
418	          if (argCount === 0 && !chars.includes(optionString[1]) && explicitArg !== '') {
419	            // A single-dash flag with something glued to it: try to read the
420	            // tail as further short options, as in `-hx` -> `-h` then `-x`.
421	            // An explicit `=` or a dash-prefixed tail is a hard error instead.
422	            if (sep || chars.includes(explicitArg[0])) {
423	              throw new ArgumentError(action, `ignored explicit argument '${explicitArg}'`);
424	            }
425	            actionTuples.push([action, [], optionString]);
426	            const char = optionString[0];
427	            optionString = char + explicitArg[0];
428	            if (this.optionStringActions.has(optionString)) {
429	              action = this.optionStringActions.get(optionString);
430	              explicitArg = explicitArg.slice(1);
431	              if (explicitArg === '') {
432	                sep = null;
433	                explicitArg = null;
434	              } else if (explicitArg[0] === '=') {
435	                sep = '=';
436	                explicitArg = explicitArg.slice(1);
437	              } else {
438	                sep = '';
439	              }
440	              continue;
441	            }
442	            extras.push(char + explicitArg);
443	            stop = startIndex + 1;
444	            break;
445	          }
446	
447	          if (argCount === 1) {
448	            stop = startIndex + 1;
449	            actionTuples.push([action, [explicitArg], optionString]);
450	            break;
451	          }
452	
453	          throw new ArgumentError(action, `ignored explicit argument '${explicitArg}'`);
454	        }
455	
456	        const start = startIndex + 1;
457	        const argCount = this.matchArgument(action, pattern.slice(start));
458	        stop = start + argCount;
459	        actionTuples.push([action, args.slice(start, stop)]);
460	        break;
461	      }
462	
463	      for (const [tupleAction, values] of actionTuples) takeAction(tupleAction, values);
464	      return stop;
465	    };
466	
467	    const optionKeys = Array.from(optionIndices.keys());
468	    const maxOptionIndex = optionKeys.length > 0 ? Math.max(...optionKeys) : -1;
469	
470	    let startIndex = 0;
471	    try {
472	      while (startIndex <= maxOptionIndex) {
473	        const nextOptionIndex = Math.min(...optionKeys.filter((index) => index >= startIndex));
474	        // No positionals are declared, so anything before the next option is
475	        // unparseable and goes straight to extras.
476	        if (startIndex !== nextOptionIndex) {
477	          extras.push(...args.slice(startIndex, nextOptionIndex));
478	          startIndex = nextOptionIndex;
479	        }
480	        startIndex = consumeOptional(nextOptionIndex);
481	      }
482	    } catch (err) {
483	      if (err instanceof ArgumentError) this.error(err.message);
484	      throw err;
485	    }
486	
487	    extras.push(...args.slice(startIndex));
488	
489	    const missing = this.actions
490	      .filter((action) => action.required && !seenActions.has(action))
491	      .map((action) => action.optionStrings.join('/'));
492	    if (missing.length > 0) {
493	      this.error(`the following arguments are required: ${missing.join(', ')}`);
494	    }
495	
496	    return [namespace, extras];
497	  }
